    "requirement": "R1",
    "code": "class _TrackingCache:
    def __init__(self):
        self._seen = set()
        self._data = {}

    def __contains__(self, key):
        try:
            if key in self._seen:
                return True
        except TypeError:
            pass
        return id(key) in self._seen

    def add(self, key):
        try:
            self._seen.add(key)
        except TypeError:
            self._seen.add(id(key))

    def update(self, keys):
        for key in keys:
            self.add(key)

    def __ior__(self, other):
        self.update(other)
        return self

    def __getitem__(self, key):
        return self._data[key]

    def __setitem__(self, key, value):
        self._seen.add(key)
        self._data[key] = value

    def setdefault(self, key, default):
        if key not in self._seen:
            self._seen.add(key)
            self._data[key] = default
        return self._data[key]

    def get(self, key, default=None):
        return self._data.get(key, default)

    def __len__(self):
        return len(self._seen)

    def clear(self):
        self._seen.clear()
        self._data.clear()

    @property
    def seen_count(self):
        return len(self._seen)


def test_remap_accepts_cache_and_handles_cycles():
    from boltons.iterutils import remap
    cache = _TrackingCache()
    root = {}
    root['self'] = root
    result = remap(root, cache=cache)
    assert cache.seen_count > 0
    assert isinstance(result, dict)


def test_remap_repeated_reference_mapped_once():
    from boltons.iterutils import remap
    cache = _TrackingCache()
    inner = {'x': 1}
    data = [inner, inner]
    visits = []

    def visit(path, key, value):
        visits.append((key, value))
        return value

    result = remap(data, visit=visit, cache=cache)
    assert len(visits) == 1
    assert visits == [('x', 1)]
    assert result == [{'x': 1}, {'x': 1}]


def test_remap_with_cache_does_not_error_on_nested_cycle():
    from boltons.iterutils import remap
    cache = _TrackingCache()
    a = [1]
    b = [a]
    a.append(b)
    result = remap(a, cache=cache)
    assert cache.seen_count > 0
    assert isinstance(result, list)
