def test_research_accepts_cache_and_finds_leaf_in_cycle():
    from boltons.iterutils import research
    cache = _TrackingCache()
    root = {'leaf': 1}
    root['self'] = root
    paths = list(research(root, query=lambda p, k, v: k == 'leaf', cache=cache))
    assert cache.seen_count > 0
    assert any(path and path[-1] == 'leaf' for path in paths)


def test_research_forwards_cache_to_internal_remap():
    from boltons.iterutils import research
    cache = _TrackingCache()
    root = {'a': [1, 2]}
    paths = list(research(root, query=lambda p, k, v: isinstance(v, int), cache=cache))
    assert cache.seen_count > 0
    assert len(paths) == 2


def test_research_with_cache_no_errors_on_circular_nesting():
    from boltons.iterutils import research
    cache = _TrackingCache()
    root = {}
    cur = root
    for _ in range(10):
        cur['child'] = {}
        cur = cur['child']
    cur['self'] = root
    paths = list(research(root, query=lambda p, k, v: k == 'child', cache=cache))
    assert cache.seen_count > 0
    assert len(paths) >= 1
